-- Aroma Israel Menu Seed milestone.
--
-- Run this file manually, once, in the Supabase Dashboard -> SQL Editor,
-- after 001_trainees.sql .. 009_restaurant_food_items.sql.
--
-- Purpose: seed public.restaurant_food_items (created empty by migration
-- 009) with the first restaurant/food-chain dataset: Aroma Israel ("ארומה").
-- This is the FIRST chain in the new, separate restaurant-food system —
-- it does not touch public.food_reference_catalog in any way, and does not
-- modify migration 009 or any earlier migration.
--
-- Source: every row below was individually verified against Aroma
-- Israel's own official per-item nutrition page,
--   https://www.aroma.co.il/food/<item>/
-- which is the calorie disclosure Israeli law requires chains with 12+
-- branches to publish (not a third-party estimate). Values are the actual
-- menu serving as sold (a whole sandwich, a specific cup size, a bowl) —
-- never per 100g. Checked 2026-08-05; the site itself stamps each table
-- "last updated 27.7.26" (2026-07-27).
--
-- Coverage: 159 of the 170 items on Aroma's current menu (every category:
-- hot drinks, pastries, sandwiches on both כריך and מחמצת bread, salads,
-- bowls, breakfasts, toasts on both breads, fresh juices, iced coffee,
-- cold drinks, shakes, soups, breads & sauces). The remaining 11 menu
-- items were checked and deliberately excluded because Aroma has not
-- published usable calorie figures for them (plain espresso/black
-- coffee/tea, affogato, con panna, iced Americano, iced chai latte, a
-- fruit & granola parfait, and the scooped-to-order ice cream, which only
-- has a per-100g figure and no fixed serving weight) — see the research
-- report for the full list. Nothing was estimated or invented to fill
-- those gaps.
--
-- Safe to run once: relies on the unique index from 009
-- (restaurant_food_items_chain_item_serving_idx) to prevent duplicates on
-- a second run — a repeat run would fail on the first conflicting row
-- rather than silently double-inserting.

insert into public.restaurant_food_items
  (chain_name, item_name, serving_description, calories_per_serving, protein_per_serving, source_url, source_name, source_checked_at)
values

